/// Task 1:
/// Given a non-empty collection of dtypes, return a dtype that appears in the
/// collection and has maximum precedence among the elements.
///
/// Panics if `types` is empty (per problem statement, input is non-empty).
pub fn find_max_precedence_type(types: Vec<DType>) -> DType {
    types
        .into_iter()
        .max_by_key(|t| t.precedence())
        .expect("types must be non-empty")
}

/// Task 2:
/// Determine the common dtype given array dtypes and scalar dtypes.
///
/// Rules:
/// - If only array dtypes provided: max-precedence dtype from arrays.
/// - If only scalar dtypes provided: max-precedence dtype from scalars.
/// - If both provided:
///   - let amax = max dtype in arrays; smax = max dtype in scalars
///   - if amax.kind() == smax.kind(): return amax
///   - else return smax
///
/// Returns `None` only if both inputs are empty.
pub fn find_common_type(array_types: Vec<DType>, scalar_types: Vec<DType>) -> Option<DType> {
    match (array_types.is_empty(), scalar_types.is_empty()) {
        (true, true) => None,
        (false, true) => Some(find_max_precedence_type(array_types)),
        (true, false) => Some(find_max_precedence_type(scalar_types)),
        (false, false) => {
            let amax = find_max_precedence_type(array_types);
            let smax = find_max_precedence_type(scalar_types);
            if amax.kind() == smax.kind() {
                Some(amax)
            } else {
                Some(smax)
            }
        }
    }
}

